import { useState } from 'react';
import { INITIAL_EMAILS, INITIAL_SHADOWCHAT_FEED } from '../data/commsData';
import { useOSStore } from '../store/useOSStore';

const NAV_ITEMS = [
  { id: 'inbox', label: 'Inbox' },
  { id: 'secure', label: 'Secure chat' },
  { id: 'alerts', label: 'Alerts' },
];

export default function CommsApp() {
  const [activeTab, setActiveTab] = useState('inbox');
  const [selectedMessage, setSelectedMessage] = useState(null);
  const [isComposing, setIsComposing] = useState(false);
  const [draft, setDraft] = useState('');
  const [notice, setNotice] = useState('Select a channel to begin.');
  const claimedComms = useOSStore((state) => state.gameplay.claimedComms);
  const claimCommsAttachment = useOSStore((state) => state.claimCommsAttachment);

  const openTab = (tab) => {
    setActiveTab(tab);
    setSelectedMessage(null);
    setIsComposing(false);
    setNotice(tab === 'secure' ? 'Secure relay connected.' : `${tab[0].toUpperCase()}${tab.slice(1)} channel active.`);
  };

  const openMessage = (message) => {
    setSelectedMessage(message);
    setIsComposing(false);
    setNotice(`Transmission from ${message.sender} opened.`);
  };

  const claimAttachment = () => {
    if (!selectedMessage?.attachment || claimedComms.includes(selectedMessage.id)) return;
    claimCommsAttachment(selectedMessage.id, selectedMessage.attachment.amount, 50);
    setNotice(`${selectedMessage.attachment.name} claimed.`);
  };

  const sendDraft = () => {
    if (!draft.trim()) return;
    setDraft('');
    setIsComposing(false);
    setNotice('Reply queued through the secure relay.');
  };

  const visibleMessage = selectedMessage || INITIAL_EMAILS[0];
  const attachmentClaimed = visibleMessage?.attachment && claimedComms.includes(visibleMessage.id);

  return (
    <section className="relative h-full w-full overflow-hidden bg-[#240724]" aria-label="Comms portal">
      <img
        src="/comms_window.svg"
        alt="Comms portal artwork"
        draggable={false}
        className="pointer-events-none absolute inset-0 block h-full w-full select-none object-fill"
      />

      <div className="absolute left-[1%] top-[11%] flex w-[21.5%] flex-col gap-[1.4%]">
        {NAV_ITEMS.map((item) => (
          <button
            key={item.id}
            type="button"
            onClick={() => openTab(item.id)}
            className={`h-[8.2%] min-h-5 rounded-sm border text-left text-[clamp(7px,1vw,12px)] font-semibold uppercase tracking-[.12em] transition focus:outline-none focus:ring-2 focus:ring-white/80 ${
              activeTab === item.id ? 'border-white/70 bg-white/20 text-white' : 'border-transparent bg-transparent text-white/0 hover:border-white/45 hover:bg-white/10'
            }`}
            aria-pressed={activeTab === item.id}
          >
            <span className="sr-only">{item.label}</span>
          </button>
        ))}
      </div>

      <div className="absolute left-[26.5%] top-[4%] flex max-w-[65%] items-center gap-2 rounded-full border border-white/20 bg-[#240724]/35 px-3 py-1 text-[clamp(8px,1vw,12px)] text-white/90 backdrop-blur-[2px]">
        <span className="h-1.5 w-1.5 rounded-full bg-[#b9f4d0] shadow-[0_0_8px_#b9f4d0]" />
        <span>{notice}</span>
      </div>

      <button
        type="button"
        onClick={() => openMessage(INITIAL_EMAILS[activeTab === 'alerts' ? 7 : 0])}
        className="absolute left-[26.5%] top-[16%] h-[57%] w-[68%] rounded-sm border border-transparent bg-transparent transition hover:border-white/45 hover:bg-white/5 focus:outline-none focus:ring-2 focus:ring-white/80"
        aria-label="Open current transmission"
      />

      <button
        type="button"
        onClick={() => {
          setIsComposing(true);
          setSelectedMessage(null);
          setNotice('Compose a secure reply.');
        }}
        className="absolute bottom-[10.5%] left-[27%] h-[8.5%] w-[65%] rounded-sm border border-transparent bg-transparent transition hover:border-white/55 hover:bg-white/10 focus:outline-none focus:ring-2 focus:ring-white/80"
        aria-label="Compose a message"
      />

      {activeTab === 'secure' && !selectedMessage && !isComposing && (
        <div className="absolute left-[28%] top-[17%] w-[62%] space-y-2 rounded-lg border border-white/25 bg-[#240724]/45 p-3 text-[clamp(8px,1vw,12px)] text-white/90 backdrop-blur-sm">
          {INITIAL_SHADOWCHAT_FEED.map((message) => (
            <button key={message.id} type="button" onClick={() => setNotice(`Secure channel: ${message.user}`)} className="block w-full rounded px-2 py-1 text-left hover:bg-white/15 focus:outline-none focus:ring-1 focus:ring-white">
              <span className="font-bold">{message.user}</span><span className="ml-2 text-white/65">{message.text}</span>
            </button>
          ))}
        </div>
      )}

      {selectedMessage && (
        <article className="absolute bottom-[18%] left-[28%] w-[61%] rounded-lg border border-white/30 bg-[#240724]/55 p-3 text-[clamp(8px,1vw,12px)] text-white backdrop-blur-md">
          <div className="flex items-start justify-between gap-3">
            <div><p className="font-bold">{visibleMessage.subject}</p><p className="mt-0.5 text-white/65">{visibleMessage.sender} · {visibleMessage.time}</p></div>
            <button type="button" onClick={() => setSelectedMessage(null)} className="rounded px-1 text-white/70 hover:bg-white/15 hover:text-white" aria-label="Close message">×</button>
          </div>
          <p className="mt-2 max-h-16 overflow-auto whitespace-pre-line leading-relaxed text-white/85">{visibleMessage.body}</p>
          {visibleMessage.attachment && (
            <button type="button" disabled={attachmentClaimed} onClick={claimAttachment} className="mt-2 rounded border border-white/35 bg-white/10 px-2 py-1 text-[0.9em] font-semibold hover:bg-white/20 disabled:cursor-default disabled:opacity-60">
              {attachmentClaimed ? 'Attachment claimed' : `Claim ${visibleMessage.attachment.name}`}
            </button>
          )}
        </article>
      )}

      {isComposing && (
        <form onSubmit={(event) => { event.preventDefault(); sendDraft(); }} className="absolute bottom-[18%] left-[28%] w-[61%] rounded-lg border border-white/30 bg-[#240724]/55 p-3 text-[clamp(8px,1vw,12px)] text-white backdrop-blur-md">
          <label className="block font-semibold">Secure reply</label>
          <textarea value={draft} onChange={(event) => setDraft(event.target.value)} autoFocus placeholder="Write a message…" className="mt-2 h-16 w-full resize-none rounded border border-white/25 bg-black/15 p-2 text-inherit outline-none placeholder:text-white/45 focus:border-white/60" />
          <div className="mt-2 flex justify-end gap-2"><button type="button" onClick={() => setIsComposing(false)} className="rounded px-2 py-1 hover:bg-white/15">Cancel</button><button type="submit" className="rounded border border-white/35 bg-white/15 px-2 py-1 font-semibold hover:bg-white/25">Send</button></div>
        </form>
      )}
    </section>
  );
}
